def sort_words_by_vowel_count(words):
    def vowel_count(w):
        return sum(1 for c in w.lower() if c in 'aeiou')
    return sorted(words, key=lambda w: (vowel_count(w), w))

def mode_value(nums):
    from collections import Counter
    c = Counter(nums)
    max_freq = max(c.values())
    candidates = [v for v, f in c.items() if f == max_freq]
    return min(candidates)

def sort_by_abs_diff_from_median(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        median = s[n // 2]
    else:
        median = (s[n // 2 - 1] + s[n // 2]) / 2
    return sorted(nums, key=lambda x: (abs(x - median), x))

def sort_matrix_rows_by_sum(matrix):
    def first_elem(row):
        return row[0] if row else 0
    return sorted(matrix, key=lambda row: (sum(row), first_elem(row)))

def rank_percentile_of_value(nums, x):
    count = sum(1 for n in nums if n < x)
    return round(count / len(nums) * 100, 2)
